/* Shared N26 battlefield-condition choices. Selection never changes a roster or Territory. */
(function(){'use strict';
const E=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),T=(en,ko)=>window.UKI18n?.language==='ko'?ko:en,L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(T(en,ko))}</span>`;
const effectRows=[
 ['bullet-den','Reload allowance','장전',['Once per gang each round, Reload may be a Free action.','각 갱이 라운드마다 한 번 리로드를 프리 행동으로 수행할 수 있습니다.']],
 ['rogue-doc-shop','Recovery assistance','회복 지원',['Assistance adds two Injury dice instead of the usual one.','회복 지원으로 추가하는 부상 주사위가 보통 1개에서 2개로 늘어납니다.']],
 ['mess-shack','Leadership','리더십',['All models gain +1 Leadership.','모든 모델의 리더십 특성이 1 증가합니다.']],
 ['drinking-hole','First-round restriction','첫 라운드 제한',['Ranged weapons cannot be used in round 1.','1라운드에는 원거리 무기를 사용할 수 없습니다.']],
 ['fence-hangout','Side Job reward','사이드 잡 보상',['Completing a Side Job earns the gang an additional D3×10 credits.','사이드 잡을 완수한 갱은 D3×10크레딧을 추가로 얻습니다.']],
 ['bounty-den','Additional objective','추가 부가 목표',['Each player generates one additional Side Job.','각 플레이어가 사이드 잡을 1개 추가 생성합니다.']],
 ['generatorium','Visibility exception','시야 제한 예외',['Visibility (X inches) has no effect.','비지빌리티(X인치) 규칙이 효과를 내지 않습니다.']],
 ['corpse-farm','OOA reward','전투 불능 보상',['Each enemy model taken OOA earns the gang 10 credits.','적 모델을 OOA로 만들 때마다 해당 갱이 10크레딧을 얻습니다.']],
 ['tunnels','Tunnel Warfare','터널 전투',['Apply Tunnel Warfare: no climbing over walls or using stairs or ladders.','터널 워페어를 적용하여 벽 넘기와 계단·사다리 사용이 제한됩니다.']],
 ['tech-bazaar','First-round weapon restriction','첫 라운드 무장 제한',['In round 1, weapons with Blast (3/5 inches) or Template cannot be used.','1라운드에는 블라스트(3/5인치) 또는 템플릿 특성 무기를 사용할 수 없습니다.']],
 ['promethium-cache','Blaze','블레이즈',['The source example changes Blaze (5+) to Blaze (4+). Its wording about increasing X conflicts with that example: agree how to apply it before rolling.','원문 예시는 블레이즈(5+)를 블레이즈(4+)로 바꿉니다. X를 증가시킨다는 본문과 예시 표기가 엇갈리므로 굴림 전에 적용 방식을 확인하세요.']],
 ['collapsed-dome','Dangerous footing','위험한 발판',['A natural 1 on an Agility test causes an additional unsaveable, automatically wounding Str –/AP –/L1 hit.','어질리티 테스트의 자연 1은 자동 운드·세이브 불가인 Str –/AP –/L1 추가 명중을 줍니다.']],
 ['bone-shrine','Shrine objective','슈라인 목표',['The defender places a shrine within 6 inches of the centre; Fighters can control it like an objective to gain XP.','방어자가 중심 6인치 안에 슈라인을 놓습니다. 파이터는 목표처럼 통제하여 XP를 얻을 수 있습니다.']],
 ['mine-workings','Limited visibility','시야 제한',['Apply Visibility (18 inches).','비지빌리티(18인치)를 적용합니다.']],
 ['gambling-den','One reroll','재굴림',['Each player may reroll one die once during the battle.','각 플레이어가 전투 중 주사위 1개를 한 번 재굴림할 수 있습니다.']],
 ['synth-still','Toxin weapon AP','톡신 무기 AP',['Improve AP by 1 for every weapon with Toxin (X+).','톡신(X+) 특성 무기의 AP를 1 향상합니다.']],
 ['old-ruins','Long-range protection','장거리 방어',['Models at the weapon’s long range and not in cover improve their Save characteristic by 1.','무기의 장거리 구간에 있고 엄폐하지 않은 모델은 세이브 특성이 1 향상됩니다.']],
 ['fighting-pit','Close-combat XP','근접전 경험치',['Gain an additional 1 XP for causing an enemy to become Seriously Injured/Damaged or OOA with a close-combat attack.','근접 공격으로 적을 중상·중손상 또는 OOA로 만들면 XP를 1 추가로 얻습니다.']]
];
function entries(){return effectRows.flatMap(([slug,en,ko,text])=>{const row=(window.RULES_DATA?.territories||[]).find(r=>r.id==='official-003-territory-'+slug&&r.source_verified&&String(r.edition_slug||r.edition).toLowerCase()==='n26'&&r.rule_data?.battlefield_effect);return row?[{id:row.id,name:row.rule_data.battlefield_effect.name||en,nameKo:ko,territoryName:row.name,territoryNameKo:row.name_ko||row.name,descriptionEn:text[0],descriptionKo:text[1]}]:[];});}
function normalize(value){const mode=['none','manual','random'].includes(value?.mode)?value.mode:'none',effectId=typeof value?.effectId==='string'&&entries().some(row=>row.id===value.effectId)?value.effectId:'';return {mode,effectId:mode==='none'?'':effectId};}
function isResolved(value){const selected=normalize(value);return selected.mode==='none'||!!selected.effectId;}
function draw(){const rows=entries();if(!rows.length)return null;const random=new Uint32Array(1),ceiling=Math.floor(4294967296/rows.length)*rows.length;do{crypto.getRandomValues(random);}while(random[0]>=ceiling);return {mode:'random',effectId:rows[random[0]%rows.length].id};}
function markup(value,{scope='skirmish',editable=true}={}){
 const selected=normalize(value),rows=entries(),chosen=rows.find(row=>row.id===selected.effectId),context=scope==='campaign'?'campaign':'skirmish';
 const options=[['none','None','없음'],['random','Random','랜덤'],['manual','Choose directly','직접 선택']];
 const controls=editable?`<div class="bfe-controls"><label class="bfe-mode">${L('Selection method','발생 방식')}<select name="battlefieldEffectMode" data-bfe-mode>${options.map(([mode,en,ko])=>`<option value="${mode}" ${selected.mode===mode?'selected':''} data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(T(en,ko))}</option>`).join('')}</select></label>${selected.mode==='manual'?`<label class="bfe-choice">${L('Choose a battlefield effect','전장 효과 직접 선택')}<select name="battlefieldEffectId" data-bfe-id required ${rows.length?'':'disabled'}><option value="" data-i18n-en="Select an effect" data-i18n-ko="효과를 선택하세요">${E(T('Select an effect','효과를 선택하세요'))}</option>${rows.map(row=>`<option value="${E(row.id)}" ${row.id===selected.effectId?'selected':''} data-i18n-en="${E(row.name+' · '+row.territoryName)}" data-i18n-ko="${E(row.nameKo+' · '+row.territoryNameKo)}">${E(T(row.name+' · '+row.territoryName,row.nameKo+' · '+row.territoryNameKo))}</option>`).join('')}</select></label>`:`<input type="hidden" name="battlefieldEffectId" data-bfe-id value="${E(selected.effectId)}">`}${selected.mode==='random'?`<button type="button" class="btn" data-bfe-action="roll" ${rows.length?'':'disabled'}>${selected.effectId?L('Draw again','다시 뽑기'):L('Draw random effect','랜덤 효과 뽑기')}</button>`:''}</div>`:'';
 const result=chosen?`<strong class="bfe-result-name">${L(chosen.name,chosen.nameKo)}</strong><small>${L(chosen.territoryName,chosen.territoryNameKo)} · ${selected.mode==='random'?L('Random result','랜덤 결과'):L('Direct choice','직접 선택')}</small><p class="bfe-description">${L(chosen.descriptionEn,chosen.descriptionKo)}</p><button type="button" class="btn small" data-rule-term="${E(chosen.id)}" data-rule-edition="n26" aria-haspopup="dialog">${L('View source rule','출처 룰 보기')}</button>`:selected.mode==='none'?`<p class="bfe-empty">${L('No additional battlefield effect.','추가 전장 효과 없음')}</p>`:`<p class="bfe-empty">${selected.mode==='random'?L('Draw an effect to finish this selection.','랜덤 효과를 뽑아 선택을 완료하세요.'):L('Select an effect from the list.','목록에서 효과를 선택하세요.')}</p>`;
 const title=L('Battlefield effect','전장 효과'),note=!editable?L('Recorded condition for this battle. Territory-stake effects apply separately.','이번 전투에 저장된 조건입니다. 영토 내기로 정해진 효과는 별도로 적용합니다.'):context==='campaign'?L('Choose an additional condition for this battle. Effects required by the Territory stake still apply separately.','이번 전투에 추가할 조건을 선택합니다. 영토 내기로 정해진 효과는 별도로 적용합니다.'):L('Choose one agreed condition for this battle, draw one at random, or select None.','이번 전투에 쓸 효과 하나를 직접 고르거나 랜덤으로 뽑으세요. 효과 없이 진행하려면 ‘없음’을 선택하세요.');
 return `<${editable?'fieldset':'section'} class="bfe-picker" data-bfe-scope="${context}">${editable?`<legend>${title}</legend>`:`<strong>${title}</strong>`}${controls}<div class="bfe-result" role="status" aria-live="polite" aria-atomic="true">${result}</div><p class="bfe-note">${note}</p></${editable?'fieldset':'section'}>`;
}
window.MMBattlefieldEffects={entries,normalize,isResolved,draw,markup};
})();
